// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetSigningKeySet The public signing key set
	// (GET /.well-known/cipherframe-keys.json)
	GetSigningKeySet(ctx context.Context, request GetSigningKeySetRequestObject) (GetSigningKeySetResponseObject, error)
	// GetHealthz Liveness
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// CreateBrowserPlaybackSession Start a playback session from the viewer's browser
	// (POST /v1/play/tenants/{tenant_id}/sessions)
	CreateBrowserPlaybackSession(ctx context.Context, request CreateBrowserPlaybackSessionRequestObject) (CreateBrowserPlaybackSessionResponseObject, error)
	// EndPlayback End the session
	// (POST /v1/play/{session_id}/end)
	EndPlayback(ctx context.Context, request EndPlaybackRequestObject) (EndPlaybackResponseObject, error)
	// HeartbeatPlayback Heartbeat
	// (POST /v1/play/{session_id}/heartbeat)
	HeartbeatPlayback(ctx context.Context, request HeartbeatPlaybackRequestObject) (HeartbeatPlaybackResponseObject, error)
	// GetPlaybackKey Content key
	// (GET /v1/play/{session_id}/key)
	GetPlaybackKey(ctx context.Context, request GetPlaybackKeyRequestObject) (GetPlaybackKeyResponseObject, error)
	// GetPlaybackMaster Session master playlist
	// (GET /v1/play/{session_id}/master.m3u8)
	GetPlaybackMaster(ctx context.Context, request GetPlaybackMasterRequestObject) (GetPlaybackMasterResponseObject, error)
	// GetPlaybackMedia Session media playlist
	// (GET /v1/play/{session_id}/{rendition}/media.m3u8)
	GetPlaybackMedia(ctx context.Context, request GetPlaybackMediaRequestObject) (GetPlaybackMediaResponseObject, error)
	// GetPlaybackSegment Init or media segment
	// (GET /v1/play/{session_id}/{rendition}/{file})
	GetPlaybackSegment(ctx context.Context, request GetPlaybackSegmentRequestObject) (GetPlaybackSegmentResponseObject, error)
	// ListUploadParts List received parts
	// (GET /v1/uploads/multipart/{asset_id}/parts)
	ListUploadParts(ctx context.Context, request ListUploadPartsRequestObject) (ListUploadPartsResponseObject, error)
	// PutUploadPart Upload one part
	// (PUT /v1/uploads/multipart/{asset_id}/parts/{part_number})
	PutUploadPart(ctx context.Context, request PutUploadPartRequestObject) (PutUploadPartResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

